using UnityEngine;
using UnityEditor;
using Unity.Netcode;
using UnityEngine.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var nm = NetworkManager.Singleton;
        if (nm == null) { result.LogError("No NetworkManager"); return; }

        // Reproduce MainMenuUI.EnterWorld for a NEW world, minus the relay allocation.
        var world = WorldSaveData.CreateNew(0, "MCPTest", Vector3.zero);
        GameSession.Instance.BeginHosting(world, true);

        bool ok = nm.StartHost();
        result.Log("StartHost={0} IsServer={1} IsListening={2}", ok, nm.IsServer, nm.IsListening);

        var status = nm.SceneManager.LoadScene(world.startScene, LoadSceneMode.Single);
        result.Log("LoadScene('{0}') status={1}", world.startScene, status);
    }
}

