using UnityEngine;
using UnityEditor;
using Unity.Netcode;
using UnityEngine.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var nm = NetworkManager.Singleton;
        result.Log("activeScene={0} isServer={1} connectedClients={2}",
            SceneManager.GetActiveScene().name, nm != null && nm.IsServer,
            nm != null ? nm.ConnectedClientsList.Count : -1);

        var items = Object.FindObjectsByType<Item>(FindObjectsInactive.Include, FindObjectsSortMode.None);
        result.Log("Item pickups after networked load: {0}", items.Length);
        foreach (var it in items)
        {
            var sr = it.GetComponentInChildren<SpriteRenderer>();
            result.Log("  - {0} type={1} handSlot={2} active={3} pos={4} bounds={5}",
                it.name, it.GetType().Name, it.handSlot, it.gameObject.activeInHierarchy,
                it.transform.position, sr != null ? sr.bounds.size.ToString() : "no SR");
        }

        var players = Object.FindObjectsByType<PlayerController>(FindObjectsSortMode.None);
        result.Log("PlayerControllers in scene: {0}", players.Length);
        foreach (var p in players)
        {
            var inv = p.GetComponent<PlayerInventory>();
            result.Log("  - player pos={0} hasInventory={1}", p.transform.position, inv != null);
        }
    }
}

