using UnityEngine;
using UnityEditor;
using System.Linq;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var inv = Object.FindFirstObjectByType<PlayerInventory>();
        if (inv == null) { result.LogError("No PlayerInventory"); return; }
        var items = Object.FindObjectsByType<Item>(FindObjectsInactive.Include, FindObjectsSortMode.None);
        Item sword = items.FirstOrDefault(i => i.name == "TestSword");
        Item axe   = items.FirstOrDefault(i => i.name == "TestAxe");
        if (sword == null || axe == null) { result.LogError("Missing sword/axe"); return; }

        inv.TryPickup(sword);
        result.Log("After pickup sword: rightActive={0} swordActiveObj={1}",
            inv.GetActive(Hand.Right)?.name, sword.gameObject.activeSelf);

        inv.TryPickup(axe);
        result.Log("After pickup axe:   rightActive={0}", inv.GetActive(Hand.Right)?.name);

        inv.Cycle(Hand.Right);
        result.Log("After cycle:        rightActive={0}", inv.GetActive(Hand.Right)?.name);

        inv.DropActive(Hand.Right);
        var dropped = inv.GetActive(Hand.Right);
        result.Log("After drop:         rightActive={0} swordActiveObj={1} swordPos={2}",
            dropped?.name, sword.gameObject.activeSelf, sword.transform.position);
    }
}

